// - GCC, Clang: -g -fpatchable-function-entry=7,5 (and -fno-ipa-icf with GCC);
//   link with -ldl -pthread
// - MSVC, clang-cl: /Z7 /hotpatch; link with /DEBUG:FULL /FUNCTIONPADMIN
//   /OPT:NOREF /OPT:NOICF /INCREMENTAL:NO and psapi.lib
